Hi,
I have some trouble understanding how Clay_OnHover works.

I created a small example (source code below) where I have two Layouts (CreateLayout0() and CreateLayout1()), both consist of one purple button and one white textfield. Layout0 has the button left and the textfield on the right and Layout1 the other way around. The button in each layout just makes the other layout appear.

I start the program, Layout0 shows up and I click the button and Layout1 is shown. So far so good.

If I now click on the textfield, I don't expect anything to happen as I didn't call Clay_OnHover for this element, but apparently my onHover function is triggered and the output shows the exact same element id and data as the button of the former Layout0, the one I clicked before.
The button in Layout1 works as expected and Layout0 is renderer again.

But then the same happens for the textfield in Layout0: It acts as it is the just clicked button from Layout1.

So my problem is that elements that shouldn't be interactive act like Clay_OnHover was called on them. I could prevent this by assigning each element its unique id, but when you look at this example (https://github.com/nicbarker/clay/blob/main/examples/clay-official-website/main.c), line 254, RendererButtonInactive doesn't declare any IDs as well. Also I want to be able to create elements dynamically, like dropdowns that show elements based on the return value of some function, and creating IDs for and keeping track of them seems unnecessarily complicated. 

```#define CLAY_IMPLEMENTATION
#include <iostream>
#include <string>

#include <clay.h>
#include <renderers/raylib/clay_renderer_raylib.c>

int layout = 0;

int Layout0 = 0;
int Layout1 = 1;

void onHover(Clay_ElementId id, Clay_PointerData pointerInfo, intptr_t data)
{
    if (pointerInfo.state == CLAY_POINTER_DATA_RELEASED_THIS_FRAME)
    {
        std::cout << id.id << "," << *reinterpret_cast<int*>(data) << std::endl;
        layout = *reinterpret_cast<int*>(data);
    }
}

Clay_RenderCommandArray CreateLayout0()
{
    Clay_BeginLayout();

    CLAY({.layout = {.sizing = {.width = CLAY_SIZING_FIT(), .height = CLAY_SIZING_FIT()}, .padding = {8, 8, 8, 8}, .childGap = 8},
          .backgroundColor = {255, 0, 0, 255}})
    {

        CLAY({.layout = {.sizing = {.width = CLAY_SIZING_FIT(), .height = CLAY_SIZING_FIT()}}, .backgroundColor = {130, 130, 255, 255}})
        {
            Clay_OnHover(onHover, reinterpret_cast<intptr_t>(&Layout1));
            CLAY_TEXT(CLAY_STRING("Click me"), CLAY_TEXT_CONFIG({.textColor = {0, 0, 0, 255}, .fontSize = 24}));
        }

        CLAY({.layout = {.sizing = {.width = CLAY_SIZING_FIT(), .height = CLAY_SIZING_FIT()}}, .backgroundColor = {255, 255, 255, 255}})
        {
            CLAY_TEXT(CLAY_STRING("Not me"), CLAY_TEXT_CONFIG({.textColor = {0, 0, 0, 255}, .fontSize = 24}));
        }
    }

    return Clay_EndLayout();
}

Clay_RenderCommandArray CreateLayout1()
{
    Clay_BeginLayout();

    CLAY({.layout = {.sizing = {.width = CLAY_SIZING_FIT(), .height = CLAY_SIZING_FIT()}, .childGap = 8}})
    {

        CLAY({.layout = {.sizing = {.width = CLAY_SIZING_FIT(), .height = CLAY_SIZING_FIT()}}, .backgroundColor = {255, 255, 255, 255}})
        {
            CLAY_TEXT(CLAY_STRING("Not this time"), CLAY_TEXT_CONFIG({.textColor = {0, 0, 0, 255}, .fontSize = 24}));
        }

        CLAY({.layout = {.sizing = {.width = CLAY_SIZING_FIT(), .height = CLAY_SIZING_FIT()}}, .backgroundColor = {130, 130, 255, 255}})
        {
            Clay_OnHover(onHover, reinterpret_cast<intptr_t>(&Layout0));
            CLAY_TEXT(CLAY_STRING("Over here now"), CLAY_TEXT_CONFIG({.textColor = {0, 0, 0, 255}, .fontSize = 24}));
        }
    }

    return Clay_EndLayout();
}

void HandleClayErrors(Clay_ErrorData errorData) { printf("%s", errorData.errorText.chars); }

int main(void)
{
    uint64_t totalMemorySize = Clay_MinMemorySize();
    Clay_Arena clayMemory = Clay_CreateArenaWithCapacityAndMemory(totalMemorySize, malloc(totalMemorySize));
    Clay_Initialize(
        clayMemory, (Clay_Dimensions){(float)GetScreenWidth(), (float)GetScreenHeight()}, (Clay_ErrorHandler){HandleClayErrors, 0});
    Clay_Raylib_Initialize(1920, 1200, "", 0);
    Font fonts[1];
